module find_base (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] y,\n    input [15:0] l,\n    output reg [15:0] b,\n    output reg done,\n    output reg valid\n);\n\n    // State definitions\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] START_SEARCH = 3'd1;\n    localparam [2:0] DIVIDE      = 3'd2;\n    localparam [2:0] CHECK_DIGITS = 3'd3;\n    localparam [2:0] CHECK_VALUE = 3'd4;\n    localparam [2:0] UPDATE_B    = 3'd5;\n    localparam [2:0] DONE_STATE  = 3'd6;\n\n    // Parameters\n    parameter MAX_B = 16'd256;\n    \n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [15:0] current_b;\n    reg [15:0] temp_y;\n    reg [15:0] best_b;\n    reg found_valid;\n    reg [3:0] digit_count;\n    reg [3:0] digit_idx;\n    reg [15:0] base10_val;\n    reg [15:0] quotient;\n    reg [15:0] remainder;\n    \n    // Digits storage\n    reg [3:0] digits [0:15];\n\n    integer i;  // Loop variable for reset\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            b <= 16'd0;\n            current_b <= 16'd0;\n            best_b <= 16'd0;\n            found_valid <= 1'b0;\n            \n            for (i = 0; i < 16; i = i + 1) begin\n                digits[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    if (start) begin\n                        current_b <= (y < MAX_B) ? y : MAX_B;\n                        found_valid <= 1'b0;\n                        best_b <= 16'd0;\n                        state <= START_SEARCH;\n                    end\n                end\n\n                START_SEARCH: begin\n                    if (current_b < 16'd2) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        temp_y <= y;\n                        digit_count <= 4'd0;\n                        state <= DIVIDE;\n                    end\n                end\n\n                DIVIDE: begin\n                    if (temp_y == 16'd0) begin\n                        state <= CHECK_DIGITS;\n                        digit_idx <= 4'd0;\n                    end else begin\n                        quotient <= temp_y / current_b;\n                        remainder <= temp_y % current_b;\n                        \n                        // Store digit\n                        digits[digit_count] <= remainder[3:0];\n                        digit_count <= digit_count + 4'd1;\n                        temp_y <= quotient;\n                        \n                        if (digit_count >= 4'd15) begin\n                            state <= CHECK_DIGITS;\n                            digit_idx <= 4'd0;\n                        end\n                    end\n                end\n\n                CHECK_DIGITS: begin\n                    if (digit_idx >= digit_count) begin\n                        // All digits valid\n                        base10_val <= 16'd0;\n                        digit_idx <= 4'd0;\n                        state <= CHECK_VALUE;\n                    end else if (digits[digit_idx] > 4'd9) begin\n                        // Invalid digit found\n                        state <= UPDATE_B;\n                    end else begin\n                        digit_idx <= digit_idx + 4'd1;\n                    end\n                end\n\n                CHECK_VALUE: begin\n                    if (digit_idx >= digit_count) begin\n                        // Value computation complete\n                        if (base10_val >= l) begin\n                            best_b <= current_b;\n                            found_valid <= 1'b1;\n                            state <= DONE_STATE;\n                        end else begin\n                            state <= UPDATE_B;\n                        end\n                    end else begin\n                        base10_val <= (base10_val * 16'd10) + digits[digit_idx];\n                        digit_idx <= digit_idx + 4'd1;\n                    end\n                end\n\n                UPDATE_B: begin\n                    current_b <= current_b - 16'd1;\n                    state <= START_SEARCH;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    valid <= found_valid;\n                    b <= found_valid ? best_b : 16'd0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule